-- =============================================================================
-- 001-sample-data.sql — dữ liệu mẫu CHUẨN cho mọi service (dev/demo)
-- =============================================================================
-- Gồm: user, thành phố/sân bay, hãng bay, máy bay, hạng ghế + sơ đồ ghế + ghế, chuyến bay + lịch bay, chuyến bay cụ thể
-- trong 30 ngày tới kèm cabin/ghế từng chuyến, fare + quy tắc hoàn/đổi + hành lý, suất ăn, hành lý mua thêm, bảo hiểm.
--
-- Chạy SAU KHI mọi service đã khởi động ít nhất một lần (schema do Hibernate ddl-auto tạo), trên DB TRỐNG (docker
-- compose mới hoặc sau `down -v`). Xem README.md cùng thư mục.
--
-- Idempotent: id cố định (tiền tố 5eed...) hoặc dẫn xuất bằng MD5 + `ON DUPLICATE KEY UPDATE id = id`, nên chạy lại không
-- nhân đôi dữ liệu; chạy lại vào ngày khác sinh thêm chuyến cho các ngày mới trong cửa sổ 30 ngày.
-- KHÔNG chạy trên DB đã có dữ liệu thật: hãng/sân bay trùng mã IATA bị bỏ qua nên chuyến sẽ trỏ tới id không tồn tại.
--
-- Tài khoản mẫu (mật khẩu chung Password@123, CHỈ DÙNG DEV):
--   admin@airline.local (SYSTEM_ADMIN); owner.vn|vj|qh|vu@airline.local (AIRLINE_OWNER);
--   customer1@airline.local, customer2@airline.local (USER)
-- Giá tiền: VND, số nguyên. Giờ khởi hành/đến theo giờ địa phương của sân bay tương ứng.
-- =============================================================================

SET NAMES utf8mb4;
SET lc_time_names = 'en_US';

-- ---------------------------------------------------------------- users (airline_user); role: 0 admin, 1 user, 2 owner
ON DUPLICATE KEY UPDATE id = id;

-- ---------------------------------------------------------------- cities (airline_location)
ON DUPLICATE KEY UPDATE id = id;

-- ---------------------------------------------------------------- airports (airline_location)
ON DUPLICATE KEY UPDATE id = id;

-- ---------------------------------------------------------------- airlines (airline)
ON DUPLICATE KEY UPDATE id = id;

-- ---------------------------------------------------------------- aircraft (airline); thương gia 2-2, phổ thông 3-3
ON DUPLICATE KEY UPDATE id = id;

-- ---------------------------------------------------------------- cabin classes + seat maps (airline_seat)
ON DUPLICATE KEY UPDATE id = id;

ON DUPLICATE KEY UPDATE id = id;

-- ---------------------------------------------------------------- seats (sinh từ seat map)
-- Hàng đánh số liên tục: thương gia trước, phổ thông nối tiếp. Hàng 12-13 phổ thông là lối thoát hiểm (EXTRA_LEGROOM).
-- Phụ thu chọn chỗ (premium_super_charge, VND): cửa sổ 60.000, lối đi 40.000, ghế giữa 0, rộng chân 200.000, thương gia 0.
  seat_type, has_extra_legroom, has_extra_width, has_power_outlet, has_tv_screen, is_active, is_available, is_booked,
  is_emergency_exit, premium_super_charge, base_price, recline_angle, seat_pitch, seat_width, version)
SELECT UNHEX(MD5(CONCAT('seat:', HEX(sm.id), ':', (n.n + COALESCE(o.off, 0)), ':', c.pos))), NOW(6), NOW(6), sm.cabin_class_id, sm.id,
  CONCAT((n.n + COALESCE(o.off, 0)), c.letter), (n.n + COALESCE(o.off, 0)), c.letter, IF((cc.name = 'ECONOMY' AND (n.n + COALESCE(o.off, 0)) IN (12, 13)), 'EXTRA_LEGROOM', c.seat_type),
  (cc.name = 'ECONOMY' AND (n.n + COALESCE(o.off, 0)) IN (12, 13)), cc.name = 'BUSINESS', cc.name = 'BUSINESS', cc.name = 'BUSINESS', 1, 1, 0, (cc.name = 'ECONOMY' AND (n.n + COALESCE(o.off, 0)) IN (12, 13)),
  CASE WHEN cc.name = 'BUSINESS' THEN 0 WHEN (cc.name = 'ECONOMY' AND (n.n + COALESCE(o.off, 0)) IN (12, 13)) THEN 200000 WHEN c.seat_type = 'WINDOW' THEN 60000
       WHEN c.seat_type = 'AISLE' THEN 40000 ELSE 0 END,
  0, IF(cc.name = 'BUSINESS', 40, 20), cc.typical_seat_pitch, cc.typical_seat_width, 0
FROM airline_seat.seat_maps sm
JOIN airline_seat.cabin_classes cc ON cc.id = sm.cabin_class_id
LEFT JOIN (SELECT cc1.id AS cabin_id, SUM(sm2.total_rows) AS off
             FROM airline_seat.cabin_classes cc1
             JOIN airline_seat.cabin_classes cc2 ON cc2.aircraft_id = cc1.aircraft_id AND cc2.display_order < cc1.display_order
             JOIN airline_seat.seat_maps sm2 ON sm2.cabin_class_id = cc2.id
            GROUP BY cc1.id) o ON o.cabin_id = cc.id
JOIN (SELECT a.d + 10 * b.d + 1 AS n FROM (SELECT 0 d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) a CROSS JOIN (SELECT 0 d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) b) n ON n.n <= sm.total_rows
JOIN (SELECT 2 l, 2 r, 0 pos, 'A' letter, 'WINDOW' seat_type
      UNION ALL SELECT 2, 2, 1, 'C', 'AISLE' UNION ALL SELECT 2, 2, 2, 'D', 'AISLE' UNION ALL SELECT 2, 2, 3, 'F', 'WINDOW'
      UNION ALL SELECT 3, 3, 0, 'A', 'WINDOW' UNION ALL SELECT 3, 3, 1, 'B', 'MIDDLE' UNION ALL SELECT 3, 3, 2, 'C', 'AISLE'
      UNION ALL SELECT 3, 3, 3, 'D', 'AISLE' UNION ALL SELECT 3, 3, 4, 'E', 'MIDDLE' UNION ALL SELECT 3, 3, 5, 'F', 'WINDOW') c
  ON c.l = sm.left_seats_per_row AND c.r = sm.right_seats_per_row
WHERE HEX(sm.id) LIKE '5EED0007%'
;

-- ---------------------------------------------------------------- flights + schedules (airline_flight); status 0 = SCHEDULED
ON DUPLICATE KEY UPDATE id = id;

ON DUPLICATE KEY UPDATE start_date = VALUES(start_date), end_date = VALUES(end_date);

-- ---------------------------------------------------------------- flight instances (30 ngày tới, theo lịch)
  arrival_airport_id, departure_date_time, arrival_date_time, total_seats, available_seats, status, is_active,
  min_advance_booking_days, max_advance_booking_days)
SELECT UNHEX(MD5(CONCAT('fi:', HEX(s.id), ':', d.day))), NOW(6), NOW(6), s.flight_id, s.id, f.airline_id, s.departure_airport_id,
  s.arrival_airport_id, TIMESTAMP(d.day, s.departure_time),
  TIMESTAMP(DATE_ADD(d.day, INTERVAL (s.arrival_time < s.departure_time) DAY), s.arrival_time),
  ac.seating_capacity, ac.seating_capacity, 'SCHEDULED', 1, 0, 365
FROM airline_flight.flight_schedules s
JOIN airline_flight.flights f ON f.id = s.flight_id
JOIN airline.aircrafts ac ON ac.id = f.aircraft_id
JOIN (SELECT DATE_ADD(CURDATE(), INTERVAL a.d + 10 * b.d + 1 DAY) AS day FROM (SELECT 0 d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) a CROSS JOIN (SELECT 0 d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) b) d
  ON d.day BETWEEN s.start_date AND s.end_date AND d.day <= DATE_ADD(CURDATE(), INTERVAL 30 DAY)
WHERE HEX(s.id) LIKE '5EED0009%' AND s.is_active = 1 AND FIND_IN_SET(UPPER(DAYNAME(d.day)), s.operating_days)
;

-- ---------------------------------------------------------------- cabin + seat instance của từng chuyến (seat-service)
-- Thay cho sự kiện Kafka flight.instance.created (seed bỏ qua Kafka), cùng quy tắc FlightInstanceCabinServiceImpl: base_fare 0
-- (giá vé lấy từ pricing-service), phụ thu mặc định cửa sổ/lối đi 1000/500, fare ghế = phụ thu riêng của ghế.
  booked_seats, base_fare, window_surcharge, aisle_surcharge, is_active)
SELECT UNHEX(MD5(CONCAT('fic:', HEX(fi.id), ':', HEX(cc.id)))), NOW(6), NOW(6), fi.id, cc.id,
  (SELECT COUNT(*) FROM airline_seat.seats se WHERE se.seat_map_id = sm.id), 0, 0, 1000, 500, 1
FROM airline_flight.flight_instances fi
JOIN airline_flight.flights f ON f.id = fi.flight_id
JOIN airline_seat.cabin_classes cc ON cc.aircraft_id = f.aircraft_id
JOIN airline_seat.seat_maps sm ON sm.cabin_class_id = cc.id
WHERE HEX(f.id) LIKE '5EED0008%'
;

  seat_id, seat_map_id, status, is_available, is_booked, premium_super_charge, fare, version)
SELECT UNHEX(MD5(CONCAT('si:', HEX(fic.id), ':', HEX(se.id)))), NOW(6), NOW(6), fi.flight_id, fi.id, fic.id, se.id, se.seat_map_id,
  'AVAILABLE', 1, 0, se.premium_super_charge, se.premium_super_charge, 0
FROM airline_seat.flight_instance_cabins fic
JOIN airline_flight.flight_instances fi ON fi.id = fic.flight_instance_id
JOIN airline_seat.seat_maps sm ON sm.cabin_class_id = fic.cabin_class_id
JOIN airline_seat.seats se ON se.seat_map_id = sm.id
WHERE HEX(fi.flight_id) LIKE '5EED0008%'
;

-- ---------------------------------------------------------------- fares + rules + baggage (airline_pricing)
-- total = base_fare + taxed_and_fees + airline_fees (+ current_price = 0). Tên fare duy nhất theo (chuyến, hạng, tên).
ON DUPLICATE KEY UPDATE id = id;

ON DUPLICATE KEY UPDATE id = id;

ON DUPLICATE KEY UPDATE id = id;

-- ---------------------------------------------------------------- ancillary (airline_ancillary)
ON DUPLICATE KEY UPDATE id = id;

ON DUPLICATE KEY UPDATE id = id;

ON DUPLICATE KEY UPDATE id = id;

-- Suất ăn của từng chuyến: mọi suất ăn của hãng đó (món chính 90.000, đồ ăn nhẹ 50.000).
SELECT UNHEX(MD5(CONCAT('fm:', HEX(f.id), ':', HEX(m.id)))), NOW(6), NOW(6), f.id, m.id, 1,
  IF(m.meal_type = 'MAIN', 90000, 50000), m.display_order
FROM airline_flight.flights f
JOIN airline_ancillary.meals m ON m.airline_id = f.airline_id
WHERE HEX(f.id) LIKE '5EED0008%' AND HEX(m.id) LIKE '5EED000F%'
;

-- Dịch vụ thêm theo (chuyến, hạng ghế): hành lý của hãng + 2 gói bảo hiểm dùng chung. Thương gia đã gồm sẵn 10kg và 20kg.
  max_quantity, price, included_in_fare)
SELECT UNHEX(MD5(CONCAT('fca:', HEX(f.id), ':', HEX(cc.id), ':', HEX(a.id)))), NOW(6), NOW(6), f.id, cc.id, a.id, 1,
  IF(a.type = 'BAGGAGE', 3, 1),
  CASE WHEN cc.name = 'BUSINESS' AND a.name IN ('Hành lý ký gửi 10kg', 'Hành lý ký gửi 20kg') THEN 0
       WHEN a.name = 'Hành lý ký gửi 10kg' THEN 150000 WHEN a.name = 'Hành lý ký gửi 20kg' THEN 250000
       WHEN a.name = 'Hành lý ký gửi 30kg' THEN 400000 WHEN a.name = 'Bảo hiểm du lịch Cơ bản' THEN 99000 ELSE 199000 END,
  cc.name = 'BUSINESS' AND a.name IN ('Hành lý ký gửi 10kg', 'Hành lý ký gửi 20kg')
FROM airline_flight.flights f
JOIN airline_seat.cabin_classes cc ON cc.aircraft_id = f.aircraft_id
JOIN airline_ancillary.ancillary a ON (a.airline_id = f.airline_id OR a.airline_id IS NULL)
WHERE HEX(f.id) LIKE '5EED0008%' AND HEX(a.id) LIKE '5EED000D%'
;

SELECT 'seed ok' AS result,
  (SELECT COUNT(*) FROM airline_flight.flight_instances WHERE HEX(flight_id) LIKE '5EED0008%') AS flight_instances,
  (SELECT COUNT(*) FROM airline_seat.seats WHERE HEX(seat_map_id) LIKE '5EED0007%') AS seats,
  (SELECT COUNT(*) FROM airline_seat.seat_instances WHERE HEX(flight_id) LIKE '5EED0008%') AS seat_instances,
  (SELECT COUNT(*) FROM airline_pricing.fares WHERE HEX(flight_id) LIKE '5EED0008%') AS fares;
